// Worker entry point: wraps the OpenNext handler with request logging and adds the daily
// analytics maintenance cron (see wrangler.jsonc "triggers"). .open-next/worker.js is
// generated by `opennextjs-cloudflare build`, so this file is excluded from tsconfig.
import handler from "./.open-next/worker.js";
import { createWorker } from "./src/worker/create-worker";

export default createWorker(handler);
